    correctKey: 'B',
    explanation: '始動補償器法＝三相単巻変圧器で降圧して始動。別の誘導電動機を直結する方式は始動電動機法であり、名称が入れ替わっている。\n【図解】同期電動機の始動方式\n　○自己始動法：制動巻線でかご形的に始動し同期へ引き込み\n　○始動補償器法：三相単巻変圧器で降圧して始動★\n　×始動補償器法＝別の誘導電動機を直結（誤り、これは始動電動機法）\n　→ 同期電動機は静止状態では始動トルクを生じない★⚠',
