    explanation: '中性線欠相時は両負荷が直列回路化し、不平衡に応じて片側に異常高電圧が生じる重大事故。中性線には単独の過電流遮断器を設けないのが原則。\n【図解】中性線欠相事故のしくみ\n　○欠相時：両負荷が直列化し不平衡に応じ電圧が偏る★\n　○対策：中性線には単独の過電流遮断器を設けない\n　×欠相しても各負荷に定格電圧が加わり続ける（誤り）⚠\n　→ 片側に異常高電圧・他側に異常低電圧が生じ機器焼損の危険★',
