    correctKey: 'C',
    explanation: 'LTC（負荷時タップ切換装置）は運転中でも切換可能。無負荷タップ切換装置は停止時のみ切換可能。両者の役割が逆になっている点が典型的な誤りパターン。\n【図解】タップ切換装置の種類\n　○無負荷タップ切換：停止時のみ切換可能★\n　○負荷時タップ切換（LTC）：運転中でも切換可能\n　×LTCは停止させないと切換できない（誤り、実際は運転中可）⚠\n　→ 配電用変電所ではLTCで自動電圧調整を行う★',
