    choices: [
      { key: 'A', text: '直接埋設式では、車両その他の重量物の圧力を受けるおそれのある場所の埋設深さは1.2m以上とする。', explanation: '適当。その他の場所は0.6m以上。ケーブルはトラフ等の防護物に収める。' },
      { key: 'B', text: '管路式は、直接埋設式に比べてケーブルの増設・引替えが困難である。', explanation: '不適当。管路式はマンホール間に敷設した管路にケーブルを引き入れる方式であり、直接埋設式に比べて増設・引替えが「容易」である。掘り返しが必要な直接埋設式のほうが増設困難であり、特徴が逆になっている。' },
      { key: 'C', text: '暗きょ式（共同溝等）では、耐燃措置を施したケーブルを使用するか、自動消火設備を施設する。', explanation: '適当。洞道内の火災対策。ケーブルの延焼防止が目的。' },
      { key: 'D', text: '地中電線路には、需要場所に施設する場合を除き、物件の名称・管理者・電圧を表示した埋設標識を、おおむね2mの間隔で設ける。', explanation: '適当。掘削事故防止のための表示。埋設シートの敷設も併用される。' },
    ],
    correctKey: 'B',
    explanation: '管路式＝増設・引替えが容易。直接埋設＝安価だが増設困難。\n【図解】地中電線路の3方式\n　直接埋設式：安価・増設困難\n　　深さ：重量物圧力あり1.2m以上★／なし0.6m以上\n　管路式：管＋マンホール → 増設・引替え容易★\n　暗きょ式：多条数向き・耐燃措置or自動消火★\n　埋設標識：おおむね2m間隔★・埋設シート併用',
    difficulty: 'standard',
