    correctKey: 'B',
    explanation: '電動機の過負荷保護にはサーマルリレーのほか、サーモスタット・測温抵抗体・電子サーマル等の複数方式がある。「他の方式は認められない」は誤り。\n【図解】電動機の過負荷保護方式\n　○サーマルリレー：始動電流で誤動作しない特性★\n　○過負荷検知で電源遮断し巻線焼損を防止\n　×サーマルリレー以外の方式は認められない（誤り）⚠\n　→ 電子サーマルは調整幅が広く詳細な設定が可能★',
    difficulty: 'standard',
