    explanation: 'クラッシングはクリティカルパス上の作業を短縮して初めて全体工期の短縮になる。フロートのある作業への資源投入は工期短縮に寄与しない。\n【図解】クラッシング（工期短縮）の考え方\n　○クリティカルパス上の作業に資源投入し所要日数を短縮★\n　○費用勾配の小さい作業から優先的に短縮するのが経済的\n　×フロートを持つ作業への投入で工期短縮（誤り）⚠\n　→ 短縮の結果、別経路が新たなクリティカルパスになることも★',
