    correctKey: 'D',
    explanation: '統括安全衛生責任者の選任は、下請負人を含む現場の労働者数が法令上の基準に達した場合に義務付けられる。「自由に決定できる」は誤り。\n【図解】安全衛生管理体制の要点\n　○統括安全衛生責任者：現場全体の安全衛生を統括★\n　○元方安全衛生管理者：技術面で統括安全衛生責任者を補佐\n　×選任要否を元方事業者が自由に決定できる（誤り）⚠\n　→ 店社安全衛生管理者は小規模現場向けの補完制度★',
    difficulty: 'advanced',
