    correctKey: 'C',
    explanation: '保安規程は事業用電気工作物の「設置者」が定めて届け出るものであり、電気主任技術者が単独で作成・変更するものではない。\n【図解】保安規程の位置づけ\n　○巡視・点検・検査、運転・操作、非常時の措置等を記載★\n　○設置者が作成・届出の責任を負う\n　×電気主任技術者が単独で作成・変更できる（誤り）⚠\n　→ 設置者は保安規程の作成・遵守に関与する立場にある★',
