    explanation: '経営事項審査は公共工事を直接請け負おうとする建設業者に義務付けられる審査であり、民間工事のみの業者には受審義務がない。\n【図解】経営事項審査（経審）\n　○経営状況・経営規模・技術力等の客観的事項を評価★\n　○結果は公共工事の入札参加資格審査に活用\n　×民間工事のみの業者も含め全業者に受審義務（誤り）⚠\n　→ 公共工事を直接請け負う場合に受審が必要★',
